using System;
namespace LoopPedal {
// Eight-line orthogonal feedback network with input diffusion and damped, time-scaled decay.
sealed class HallFx {
 readonly float[][] lines=new float[8][],diffuse=new float[4][];readonly int[] at=new int[8],da=new int[4];readonly double[] dc=new double[8];double outDcL,outDcR;readonly float[] damp=new float[8],gain=new float[8],gainTarget=new float[8],work=new float[8];readonly float[] preL=null,preR=null;int preAt,tick;public volatile float Tone=.5f;float previousTone=-1,toneAlpha=.23f,toneTarget=.23f;float previousSize=-1;
 readonly bool room;
 public HallFx():this(false){}
 public HallFx(bool room){this.room=room;preL=new float[room?193:1201];preR=new float[preL.Length];int[] lengths=room?new int[]{557,641,733,839,947,1061,1187,1327}:new int[]{2503,2791,3079,3469,3907,4217,4639,5003};for(int i=0;i<8;i++)lines[i]=new float[lengths[i]];int[] d=room?new int[]{43,67,101,157}:new int[]{149,241,353,547};for(int i=0;i<4;i++)diffuse[i]=new float[d[i]];}
 public static double Seconds(float size,bool room){double s=Math.Max(0,Math.Min(1,size));return room?.12+4.88*s*s:s<=.75?1.2+8*s:7.2*Math.Pow(18/7.2,(s-.75)/.25);}
 public void Process(float l,float r,float size,out float left,out float right){if((tick++&255)==0&&(size!=previousSize||Tone!=previousTone)){previousSize=size;previousTone=Tone;double colour=(Math.Max(0,Math.Min(1,Tone))-.5)*2;toneTarget=(float)(.23*Math.Pow(colour<0?.2:3.5,colour<0?-colour:colour));double seconds=Seconds(size,room);for(int i=0;i<8;i++)gainTarget[i]=(float)Math.Pow(.001,lines[i].Length/(48000.0*seconds));}toneAlpha+=(toneTarget-toneAlpha)*.002f;float darkMix=(float)Math.Max(0,(.23-toneAlpha)/.184);float pl=preL[preAt],pr=preR[preAt];preL[preAt]=l;preR[preAt]=r;preAt=(preAt+1)%preL.Length;float input=(pl+pr)*.5f;for(int i=0;i<4;i++){float delayed=diffuse[i][da[i]],y=delayed-input*.65f;diffuse[i][da[i]]=input+y*.65f;da[i]=(da[i]+1)%diffuse[i].Length;input=y;}left=right=0;for(int i=0;i<8;i++){float tap=lines[i][at[i]];damp[i]+=(tap-damp[i])*toneAlpha;dc[i]+=(damp[i]-dc[i])*.000654284;work[i]=(float)(damp[i]-dc[i]);gain[i]+=(gainTarget[i]-gain[i])*.002f;left+=(tap+(damp[i]-tap)*darkMix)*((i&1)==0?1:-1);right+=(tap+(damp[i]-tap)*darkMix)*((i&2)==0?1:-1);}for(int width=1;width<8;width*=2)for(int baseIndex=0;baseIndex<8;baseIndex+=2*width)for(int j=0;j<width;j++){float a=work[baseIndex+j],b=work[baseIndex+j+width];work[baseIndex+j]=a+b;work[baseIndex+j+width]=a-b;}float side=(pl-pr)*.2f;for(int i=0;i<8;i++){lines[i][at[i]]=work[i]*.35355339f*gain[i]+input*.35f+side*((i&1)==0?1:-1);at[i]=(at[i]+1)%lines[i].Length;}left*=.18f;right*=.18f;outDcL+=(left-outDcL)*.001308141;outDcR+=(right-outDcR)*.001308141;left=(float)(left-outDcL);right=(float)(right-outDcR);}
 public void Clear(){Array.Clear(dc,0,dc.Length);outDcL=outDcR=0;foreach(var a in lines)Array.Clear(a,0,a.Length);foreach(var a in diffuse)Array.Clear(a,0,a.Length);Array.Clear(damp,0,8);Array.Clear(preL,0,preL.Length);Array.Clear(preR,0,preR.Length);}
}
}
